    Vgst2Vtm = Vgsteff+2.0*Vtm;
    AbovVgst2Vtm = Abulk/Vgst2Vtm;
    Nl = Cox*Vgsteff*(1.0-AbovVgst2Vtm*Vdseff)/1.60219e-19;
